using InterviewAPI.DTOs.Session;
using InterviewAPI.Services.Interfaces;
using Moq;
using Xunit;

namespace InterviewAPI.Tests;

public class CompleteSessionUtcidTests
{
    [Fact(DisplayName="FUNC037-USR-UTCID01")] public async Task Completed_session_returns_end_capabilities(){var(c,s,_,u)=ReadTest.Create();var id=Guid.NewGuid();s.Setup(x=>x.CompleteSessionAsync(u,id,It.IsAny<CancellationToken>())).ReturnsAsync(new EndResponse{Status="Completed",CanGeneratePerformanceReport=true});var ok=Assert.IsType<Microsoft.AspNetCore.Mvc.OkObjectResult>(await c.CompleteSession(id,default));var data=Assert.IsType<InterviewAPI.DTOs.ApiResponse<EndResponse>>(ok.Value).Data!;Assert.Equal("Completed",data.Status);Assert.True(data.CanGeneratePerformanceReport);}
    [Fact(DisplayName="FUNC037-USR-UTCID02")] public async Task Invalid_session_failure_is_safely_mapped(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.CompleteSessionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new InvalidOperationException("session"));Assert.Equal(503,ReadTest.Status(await c.CompleteSession(Guid.NewGuid(),default)));}
    [Fact(DisplayName="FUNC037-USR-UTCID03")] public async Task Missing_identity_does_not_call_service(){var(c,s,_,_)=ReadTest.Create(false);Assert.Equal(503,ReadTest.Status(await c.CompleteSession(Guid.NewGuid(),default)));s.Verify(x=>x.CompleteSessionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>()),Times.Never);}
    [Fact(DisplayName="FUNC037-USR-UTCID04")] public async Task Missing_session_is_safely_mapped(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.CompleteSessionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new KeyNotFoundException());Assert.Equal(503,ReadTest.Status(await c.CompleteSession(Guid.NewGuid(),default)));}
    [Fact(DisplayName="FUNC037-USR-UTCID05")] public async Task Guid_boundaries_are_forwarded(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.CompleteSessionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ReturnsAsync(new EndResponse());Assert.Equal(200,ReadTest.Status(await c.CompleteSession(Guid.Empty,default)));Assert.Equal(200,ReadTest.Status(await c.CompleteSession(Guid.Parse("ffffffff-ffff-ffff-ffff-ffffffffffff"),default)));}
    [Fact(DisplayName="FUNC037-USR-UTCID06")] public async Task Dependency_failure_returns_service_unavailable(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.CompleteSessionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new Exception("db"));Assert.Equal(503,ReadTest.Status(await c.CompleteSession(Guid.NewGuid(),default)));}
}

public class RoomTourUtcidTests
{
    [Fact(DisplayName="FUNC038-USR-UTCID01")] public async Task Marks_room_tour_seen(){var(c,s,_,u)=ReadTest.Create();Assert.Equal(200,ReadTest.Status(await c.MarkRoomTourSeen(default)));s.Verify(x=>x.MarkRoomTourSeenAsync(u,It.IsAny<CancellationToken>()),Times.Once);}
    [Fact(DisplayName="FUNC038-USR-UTCID02")] public async Task Repeated_mark_is_idempotently_forwarded(){var(c,s,_,_)=ReadTest.Create();Assert.Equal(200,ReadTest.Status(await c.MarkRoomTourSeen(default)));Assert.Equal(200,ReadTest.Status(await c.MarkRoomTourSeen(default)));s.Verify(x=>x.MarkRoomTourSeenAsync(It.IsAny<Guid>(),It.IsAny<CancellationToken>()),Times.Exactly(2));}
    [Fact(DisplayName="FUNC038-USR-UTCID03")] public async Task Missing_identity_does_not_write(){var(c,s,_,_)=ReadTest.Create(false);Assert.Equal(503,ReadTest.Status(await c.MarkRoomTourSeen(default)));s.Verify(x=>x.MarkRoomTourSeenAsync(It.IsAny<Guid>(),It.IsAny<CancellationToken>()),Times.Never);}
    [Fact(DisplayName="FUNC038-USR-UTCID04")] public async Task Persistence_failure_returns_service_unavailable(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.MarkRoomTourSeenAsync(It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new InvalidOperationException());Assert.Equal(503,ReadTest.Status(await c.MarkRoomTourSeen(default)));}
    [Fact(DisplayName="FUNC038-USR-UTCID05")] public async Task Cancellation_token_is_forwarded(){var(c,s,_,_)=ReadTest.Create();using var source=new CancellationTokenSource();Assert.Equal(200,ReadTest.Status(await c.MarkRoomTourSeen(source.Token)));s.Verify(x=>x.MarkRoomTourSeenAsync(It.IsAny<Guid>(),source.Token),Times.Once);}
    [Fact(DisplayName="FUNC038-USR-UTCID06")] public async Task Cancellation_failure_is_safely_mapped(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.MarkRoomTourSeenAsync(It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new OperationCanceledException());Assert.Equal(503,ReadTest.Status(await c.MarkRoomTourSeen(default)));}
}

public class PauseResumeUtcidTests
{
    [Fact(DisplayName="FUNC039-USR-UTCID01")] public async Task Pause_returns_quota_state(){var(c,s,_,u)=ReadTest.Create();var id=Guid.NewGuid();s.Setup(x=>x.PauseSessionAsync(u,id,It.IsAny<CancellationToken>())).ReturnsAsync(new PauseResponse{Status="Paused",PausesRemaining=2});Assert.Equal(200,ReadTest.Status(await c.Pause(id,default)));}
    [Fact(DisplayName="FUNC039-USR-UTCID02")] public async Task Unpause_returns_recalculated_timer(){var(c,s,_,u)=ReadTest.Create();var id=Guid.NewGuid();s.Setup(x=>x.UnpauseSessionAsync(u,id,It.IsAny<CancellationToken>())).ReturnsAsync(new UnpauseResponse{Status="InProgress",RemainingSeconds=100});Assert.Equal(200,ReadTest.Status(await c.Unpause(id,default)));}
    [Fact(DisplayName="FUNC039-USR-UTCID03")] public async Task Missing_identity_prevents_pause_and_unpause(){var(c,s,_,_)=ReadTest.Create(false);Assert.Equal(503,ReadTest.Status(await c.Pause(Guid.NewGuid(),default)));Assert.Equal(503,ReadTest.Status(await c.Unpause(Guid.NewGuid(),default)));s.VerifyNoOtherCalls();}
    [Fact(DisplayName="FUNC039-USR-UTCID04")] public async Task Pause_rule_failure_is_safely_mapped(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.PauseSessionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new InvalidOperationException("limit"));Assert.Equal(503,ReadTest.Status(await c.Pause(Guid.NewGuid(),default)));}
    [Fact(DisplayName="FUNC039-USR-UTCID05")] public async Task Session_id_boundaries_are_forwarded(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.PauseSessionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ReturnsAsync(new PauseResponse());Assert.Equal(200,ReadTest.Status(await c.Pause(Guid.Empty,default)));Assert.Equal(200,ReadTest.Status(await c.Pause(Guid.Parse("ffffffff-ffff-ffff-ffff-ffffffffffff"),default)));}
    [Fact(DisplayName="FUNC039-USR-UTCID06")] public async Task Unpause_dependency_failure_returns_service_unavailable(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.UnpauseSessionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new Exception("db"));Assert.Equal(503,ReadTest.Status(await c.Unpause(Guid.NewGuid(),default)));}
}

public class CameraViolationUtcidTests
{
    [Fact(DisplayName="FUNC040-USR-UTCID01")] public async Task Records_camera_strike(){var(c,s,_,u)=ReadTest.Create();var id=Guid.NewGuid();var req=new ReportCameraViolationRequest{IncidentId=Guid.NewGuid(),Reason="camera_off"};s.Setup(x=>x.ReportCameraViolationAsync(u,id,req,It.IsAny<CancellationToken>())).ReturnsAsync(new ReportCameraViolationResponse{StrikeCount=1});Assert.Equal(200,ReadTest.Status(await c.ReportCameraViolation(id,req,default)));}
    [Fact(DisplayName="FUNC040-USR-UTCID02")] public async Task Duplicate_incident_returns_duplicate_state(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.ReportCameraViolationAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<ReportCameraViolationRequest>(),It.IsAny<CancellationToken>())).ReturnsAsync(new ReportCameraViolationResponse{Duplicate=true});var result=await c.ReportCameraViolation(Guid.NewGuid(),new ReportCameraViolationRequest(),default);Assert.Equal(200,ReadTest.Status(result));}
    [Fact(DisplayName="FUNC040-USR-UTCID03")] public async Task Missing_identity_prevents_recording(){var(c,s,_,_)=ReadTest.Create(false);Assert.Equal(503,ReadTest.Status(await c.ReportCameraViolation(Guid.NewGuid(),new ReportCameraViolationRequest(),default)));s.Verify(x=>x.ReportCameraViolationAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<ReportCameraViolationRequest>(),It.IsAny<CancellationToken>()),Times.Never);}
    [Fact(DisplayName="FUNC040-USR-UTCID04")] public async Task Invalid_incident_is_safely_mapped(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.ReportCameraViolationAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<ReportCameraViolationRequest>(),It.IsAny<CancellationToken>())).ThrowsAsync(new InvalidOperationException("incident"));Assert.Equal(503,ReadTest.Status(await c.ReportCameraViolation(Guid.NewGuid(),new ReportCameraViolationRequest(),default)));}
    [Fact(DisplayName="FUNC040-USR-UTCID05")] public async Task Incident_id_boundaries_are_forwarded(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.ReportCameraViolationAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<ReportCameraViolationRequest>(),It.IsAny<CancellationToken>())).ReturnsAsync(new ReportCameraViolationResponse());Assert.Equal(200,ReadTest.Status(await c.ReportCameraViolation(Guid.NewGuid(),new ReportCameraViolationRequest{IncidentId=Guid.Empty},default)));Assert.Equal(200,ReadTest.Status(await c.ReportCameraViolation(Guid.NewGuid(),new ReportCameraViolationRequest{IncidentId=Guid.Parse("ffffffff-ffff-ffff-ffff-ffffffffffff")},default)));}
    [Fact(DisplayName="FUNC040-USR-UTCID06")] public async Task Dependency_failure_returns_service_unavailable(){var(c,s,_,_)=ReadTest.Create();s.Setup(x=>x.ReportCameraViolationAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<ReportCameraViolationRequest>(),It.IsAny<CancellationToken>())).ThrowsAsync(new Exception("db"));Assert.Equal(503,ReadTest.Status(await c.ReportCameraViolation(Guid.NewGuid(),new ReportCameraViolationRequest(),default)));}
}
